{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "O-methyl-[11C]bufotenine in mice showed brain/blood radioactivity ratios greater than 1 at 5, 15, 30, and 60 minutes after i.v. injection, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "NP16 showed favorable BBB permeability in rat CSF LC-MS analysis with a brain/blood ratio of 0.38, supporting meaningful CNS access after systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CGP74588 had low brain uptake in mouse in situ brain perfusion and was restricted by Bcrp1, indicating an efflux-limited CNS-access liability in one analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple structurally related molecules show direct in vivo brain penetration after systemic administration, including brain/blood ratios >1 and favorable CSF/BBB uptake; isolated efflux-limited or low-uptake analogs are not sufficient to predict failure.",
  "evidence_gaps": [
    "Morgan similarities are low (0.25-0.31), limiting structural transfer from any single analog.",
    "No query-specific in vivo CNS exposure data are available; prediction relies on analog evidence.",
    "Residual uncertainty remains from efflux-limited and low-uptake analogs such as CGP74588 and [18F]FPOTrp."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

